using Devinno.UI.App;
using Devinno.UI.Styling;
using Devinno.UI.WinForms;

public sealed class MainForm : Form
{
    private readonly ViewControl _view = new() { Dock = DockStyle.Fill };
    private readonly DvApp _app = new() { Theme = DvTheme.Dark };
    private readonly System.Threading.Timer _poll;

    public MainForm()
    {
        ClientSize = new Size(1280, 800);
        _app.Pages.Add(new MainPage());   // DvPage 를 상속한 페이지
        _view.App = _app;
        // _view.TouchMode = true;   // 터치 패널이면 가상 키보드 사용
        Controls.Add(_view);

        // 다른 스레드에서 값을 바꾸고 갱신 요청
        _poll = new System.Threading.Timer(_ => { _app.Invalidate(); }, null, 1000, 1000);
        FormClosed += (_, _) => _poll.Dispose();
    }
}
